  static long power ( long a , long n ) {
    if ( n == 0 ) return 1 ;
    long p = power ( a , n / 2 ) ;
    p = p * p ;
    if ( n % 2 == 1 ) p = p * a ;
    return p ;
  }
  static int countIntegers ( long l , long r ) {
    long ans = 0 , i = 1 ;
    long v = power ( 2 , i ) ;
    while ( v <= r ) {
      while ( v <= r ) {
        if ( v >= l ) ans ++ ;
        v = v * 3 ;
      }
      i ++ ;
      v = power ( 2 , i ) ;
    }
    if ( l == 1 ) ans ++ ;
    return ( int ) ans ;
  }
  public static void main ( String [ ] args ) {
    long l = 12 , r = 21 ;
    System . out . println ( countIntegers ( l , r ) ) ;
  }
}

