function binomialCoeff ( n , k ) {
  let res = 1 ;
  if ( k > n - k ) k = n - k ;
  for ( let i = 0 ;
  i < k ;
  ++ i ) {
    res *= ( n - i ) ;
    res /= ( i + 1 ) ;
  }
  return res ;
}
function catalan ( n ) {
  let c = binomialCoeff ( 2 * n , n ) ;
  return c / ( n + 1 ) ;
}
function findWays ( n ) {
  if ( n & 1 ) return 0 ;
  return catalan ( n / 2 ) ;
}
