  static final int N = 4 ;
  static boolean binarySearch1D ( int arr [ ] , int K ) {
    int low = 0 ;
    int high = N - 1 ;
    while ( low <= high ) {
      int mid = low + ( high - low ) / 2 ;
      if ( arr [ mid ] == K ) {
        return true ;
      }
      if ( arr [ mid ] < K ) {
        low = mid + 1 ;
      }
      else {
        high = mid - 1 ;
      }
    }
    return false ;
