        return binarySearch1D ( matrix [ mid ] , K ) ;
      }
      if ( K < matrix [ mid ] [ 0 ] ) {
        high = mid - 1 ;
      }
      else {
        low = mid + 1 ;
      }
    }
    return false ;
  }
