public class TYU {
  static long mod = 1000000007 ;
  static long power ( long a , long b ) {
    long res = 1 ;
    while ( b != 0 ) {
      if ( ( b & 1 ) != 0 ) {
        res *= a ;
        res %= mod ;
      }
      b /= 2 ;
      a *= a ;
      a %= mod ;
    }
    return res ;
  }
  static long minPlayer ( long n , long k ) {
    long num = ( ( power ( k , n ) - 1 ) + mod ) % mod ;
    long den = ( power ( k - 1 , mod - 2 ) + mod ) % mod ;
    long ans = ( ( ( num * den ) % mod ) * k ) % mod ;
