    while ( true ) {
      double mid = ( start + end ) / 2 ;
      double error = diff ( n , mid ) ;
      if ( error <= e ) return mid ;
      if ( ( mid * mid * mid ) > n ) end = mid ;
      else start = mid ;
    }
  }
