class GFG {
  static int factorial ( int n ) {
    int res = 1 ;
    for ( int i = 1 ;
    i <= n ;
    ++ i ) {
      res *= i ;
    }
    return res ;
  }
  static int binomialCoeff ( int n , int k ) {
    int res = 1 ;
    if ( k > n - k ) k = n - k ;
    for ( int i = 0 ;
    i < k ;
    ++ i ) {
      res *= ( n - i ) ;
      res /= ( i + 1 ) ;
