class GFG {
  static float sqroot ( float s ) {
    int pSq = 0 ;
    int N = 0 ;
    for ( int i = ( int ) ( s ) ;
    i > 0 ;
    i -- ) {
      for ( int j = 1 ;
      j < i ;
      j ++ ) {
        if ( j * j == i ) {
          pSq = i ;
          N = j ;
          break ;
        }
      }
      if ( pSq > 0 ) break ;
    }
    float d = s - pSq ;
    float P = d / ( 2.0f * N ) ;
    float A = N + P ;
    float sqrt_of_s = A - ( ( P * P ) / ( 2.0f * A ) ) ;
    return sqrt_of_s ;
  }
  public static void main ( String [ ] args ) {
    float num = 9.2345f ;
    float sqroot_of_num = sqroot ( num ) ;
    System . out . print ( "Square root of " + num + " = " + Math . round ( sqroot_of_num * 100000.0 ) / 100000.0 ) ;
  }
}

