class GFG {
  static int M = 1001 ;
  static int MOD = 998244353 ;
  static int [ ] [ ] dp = new int [ M ] [ M ] ;
  static int solve ( int idx , int diff , int N , int M , int K ) {
    if ( idx > N ) {
      if ( diff == K ) return 1 ;
      return 0 ;
    }
    if ( dp [ idx ] [ diff ] != - 1 ) return dp [ idx ] [ diff ] ;
    int ans = solve ( idx + 1 , diff , N , M , K ) ;
    ans += ( M - 1 ) * solve ( idx + 1 , diff + 1 , N , M , K ) ;
    return dp [ idx ] [ diff ] = ans % MOD ;
  }
  public static void main ( String [ ] args ) {
    int N = 3 , M = 3 , K = 0 ;
    for ( int i = 0 ;
    i <= M ;
    i ++ ) for ( int j = 0 ;
    j <= M ;
    j ++ ) dp [ i ] [ j ] = - 1 ;
    System . out . println ( ( M * solve ( 2 , 0 , N , M , K ) ) ) ;
  }
}

